// Get the current date and compute the past 7 days
const now = new Date();

// Calculate last Friday (7 days ago from the trigger Friday)
// Since the workflow runs every Friday at 17:00, we want the previous 7 days
const endDate = new Date(now);
const startDate = new Date(now);
startDate.setDate(startDate.getDate() - 7);

// Format as ISO strings for GitHub API
const since = startDate.toISOString();
const until = endDate.toISOString();

// Human-readable week range
const weekStart = startDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
const weekEnd = endDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

return [{
  json: {
    ...$input.first().json,
    since: since,
    until: until,
    weekLabel: `${weekStart} – ${weekEnd}`
  }
}];

// Aggregate all GitHub data and build prompt for Claude
const inputs = $input.all();

// The merge node combines 3 inputs: [commits, issues, prs]
// Each input may have multiple items

// Parse the merged data structure
// Input[0] = commits from first GitHub call
// Input[1] = issues from second GitHub call
// Input[2] = PRs from third GitHub call

const commits = inputs[0] ? inputs[0].json : [];
const issues = inputs[1] ? inputs[1].json : [];
const prs = inputs[2] ? inputs[2].json : [];

const config = inputs[0]?.json || {};
const repo = $json['repo'] || 'owner/repo';
const language = ($json['language'] || 'EN').toUpperCase();
const weekLabel = $json['weekLabel'] || '';

// Filter issues to only closed issues (API returns both issues and PRs)
const closedIssues = (Array.isArray(issues) ? issues : []).filter(i => !i.pull_request);
const mergedPRs = (Array.isArray(prs) ? prs : []).filter(pr => pr.merged_at);
const commitList = Array.isArray(commits) ? commits : [];

// Count by author
const commitAuthors = {};
commitList.forEach(c => {
  const author = c.commit?.author?.name || 'Unknown';
  commitAuthors[author] = (commitAuthors[author] || 0) + 1;
});

const issueLabels = {};
closedIssues.forEach(issue => {
  (issue.labels || []).forEach(label => {
    const name = typeof label === 'string' ? label : (label.name || 'unknown');
    issueLabels[name] = (issueLabels[name] || 0) + 1;
  });
});

// Determine instruction language
let langInstruction = '';
if (language === 'FR') {
  langInstruction = 'Write the entire summary in French. Use a professional yet friendly tone.';
} else if (language === 'ZH') {
  langInstruction = 'Write the entire summary in Chinese. Use a professional yet friendly tone.';
} else {
  langInstruction = 'Write the entire summary in English. Use a professional yet friendly tone.';
}

const prompt = `${langInstruction}

You are writing a weekly summary for the GitHub repository **${repo}**.

Week: ${weekLabel}

## Activity Overview
- **Commits**: ${commitList.length} commits by ${Object.keys(commitAuthors).length} contributors
- **Issues Closed**: ${closedIssues.length} issues closed
- **Pull Requests Merged**: ${mergedPRs.length} PRs merged

## Contributors (Commits)
${Object.entries(commitAuthors).sort((a, b) => b[1] - a[1]).map(([name, count]) => \`- ${name}: ${count} commit${count > 1 ? 's' : ''}\`).join('\n')}

## Closed Issues
${closedIssues.map(issue => \`- [#${issue.number}] ${issue.title}\`).join('\n') || 'No issues closed this week.'}

## Merged Pull Requests
${mergedPRs.map(pr => \`- [#${pr.number}] ${pr.title} (by ${pr.user?.login || 'unknown'})\`).join('\n') || 'No PRs merged this week.'}

## Issue Labels Distribution
${Object.entries(issueLabels).sort((a, b) => b[1] - a[1]).map(([label, count]) => \`- ${label}: ${count}\`).join('\n') || 'No labels found.'}

Please write a concise, engaging narrative summary (2-3 paragraphs) highlighting the key developments, notable contributions, and impact of this week's work. Keep it professional but warm. Focus on the most interesting changes and thank contributors where appropriate.`;

return [{
  json: {
    repo: repo,
    weekLabel: weekLabel,
    discordWebhook: $json['discordWebhook'],
    language: language,
    model: $json['claudeModel'] || 'claude-sonnet-4-20250514',
    prompt: prompt,
    stats: {
      commits: commitList.length,
      closedIssues: closedIssues.length,
      mergedPRs: mergedPRs.length,
      contributors: Object.keys(commitAuthors).length
    },
    topContributors: Object.entries(commitAuthors).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([name, count]) => ({ name, commits: count }))
  }
}];

// Format the Claude response into a Discord embed message
const claudeResponse = $input.first().json;
const summaryText = claudeResponse.content?.[0]?.text || claudeResponse.content || 'Summary not available.';

const repo = $json['repo'] || 'owner/repo';
const weekLabel = $json['weekLabel'] || '';
const stats = $json['stats'] || {};
const topContributors = $json['topContributors'] || [];

// Build the Discord embed
const embed = {
  title: `📊 Weekly Report: ${repo}`,
  description: `**Week of ${weekLabel}**\n\n${summaryText.substring(0, 4000)}`,
  color: 5814783,
  fields: [
    {
      name: '📈 Stats',
      value: `Commits: ${stats.commits || 0} | Issues Closed: ${stats.closedIssues || 0} | PRs Merged: ${stats.mergedPRs || 0}`,
      inline: false
    }
  ],
  timestamp: new Date().toISOString(),
  footer: {
    text: 'Generated by n8n Weekly Summary'
  }
};

// Add top contributors if available
if (topContributors.length > 0) {
  embed.fields.push({
    name: '🏆 Top Contributors',
    value: topContributors.map(c => `${c.name} (${c.commits} commits)`).join('\n'),
    inline: false
  });
}

// Build the full message payload
const discordPayload = {
  embeds: [embed],
  username: 'Weekly Summary Bot',
  avatar_url: 'https://github.githubassets.com/assets/GitHub-Mark-ea2971cee799.png'
};

return [{
  json: {
    discordWebhook: claudeResponse.discordWebhook || $json['discordWebhook'],
    discordPayload: discordPayload
  }
}];
